"""Argparse dispatch. Owner: skeleton unit (Group 1). LATER UNITS DO NOT EDIT THIS FILE.

Each subcommand is routed to a fixed entry point in its home module:

    collect  -> snapshot.collect_main(config, args)
    push     -> push.push_main(config, args)
    view     -> view.view_main(config, args)
    install  -> install.install_main(config, args)
    tap      -> limits.tap_main(config, args)     (internal; not in --help text)

Every *_main returns an int exit code. `config` is a config.Config.

Extending the CLI without touching this file: a home module may define
    add_arguments(parser)      # called with that subcommand's argparse parser
to declare its own flags. It is only called for the subcommand actually being
run, and only that module is imported, so `tap` (runs on every statusLine
refresh) never pays for importing curses or the installer.

Config errors: collect/push/view/install exit EXIT_CONFIG with a one-line
message. `tap` is the exception: a broken config must never break the user's
statusLine, so tap falls back to defaults.
"""

import argparse
import importlib
import sys
from typing import List, Optional

from grid_fleet import __version__, config as cfg

# Exit codes owned by the dispatcher. Stubs return EXIT_NOT_IMPLEMENTED until
# their unit lands.
EXIT_NOT_IMPLEMENTED = 2
EXIT_CONFIG = 3

# subcommand -> (module under grid_fleet, entry function name)
COMMANDS = {
    "collect": ("snapshot", "collect_main"),
    "push": ("push", "push_main"),
    "view": ("view", "view_main"),
    "install": ("install", "install_main"),
    "tap": ("limits", "tap_main"),
}

_HELP = {
    "collect": "write a local snapshot of sessions, tokens and limits",
    "push": "deliver the latest snapshot to the hub",
    "view": "terminal dashboard (run on the hub)",
    "install": "print (or with --apply, perform) the timer/statusLine install plan",
    # tap has no help text on purpose: it is internal (suppressed in listings).
}


def _load(name: str):
    return importlib.import_module("grid_fleet." + COMMANDS[name][0])


def build_parser(selected: Optional[str] = None) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="grid-fleet", description=__doc__.split("\n")[0])
    parser.add_argument("--version", action="version", version="grid-fleet " + __version__)
    sub = parser.add_subparsers(dest="command", metavar="{collect,push,view,install}")
    for name in COMMANDS:
        kwargs = {"help": _HELP[name]} if name in _HELP else {"help": argparse.SUPPRESS}
        sp = sub.add_parser(name, **kwargs)
        if name == "tap":
            # `tap -- <original command...>`; the command is split off in main()
            # before argparse sees it, so argparse never mangles its flags.
            sp.set_defaults(original_command=[])
        if name == selected:
            hook = getattr(_load(name), "add_arguments", None)
            if hook is not None:
                hook(sp)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)

    # Split `tap -- <cmd...>` at the first "--": everything after it belongs to
    # the wrapped statusLine command, verbatim (it may contain its own flags).
    tap_command = None  # type: Optional[List[str]]
    if argv[:1] == ["tap"] and "--" in argv:
        i = argv.index("--")
        argv, tap_command = argv[:i], argv[i + 1:]

    selected = argv[0] if argv and argv[0] in COMMANDS else None
    parser = build_parser(selected)
    args = parser.parse_args(argv)

    if args.command is None:
        # No subcommand: show usage on stderr and fail (argparse's own convention).
        parser.print_usage(sys.stderr)
        return 2
    if args.command == "tap":
        args.original_command = tap_command if tap_command is not None else []

    try:
        config = cfg.load_config()
    except cfg.ConfigError as exc:
        if args.command != "tap":
            sys.stderr.write("grid-fleet: config error: %s\n" % exc)
            return EXIT_CONFIG
        # Never break the user's statusLine over a bad config: use defaults.
        config = cfg.Config()

    module_name, func_name = COMMANDS[args.command]
    entry = getattr(_load(args.command), func_name)
    return entry(config, args)
